pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // Deploy a helper contract that will call owner() on behalf of the fuzzed EOA
        OwnerCaller helper = new OwnerCaller();
        // The fuzzed address deploys the helper, so helper acts on its behalf via tx.origin
        vm.prank(caller);
        address reportedOwner = helper.callOwnerOf(c);
        // The correct behavior: owner() returns the _owner stored (the deployer of C, which is this test contract).
        // The mutant breaks because helper.callOwnerOf has tx.origin == caller, but _owner is still the test contract.
        // So the reported owner must match the actual owner set at deployment (address(this)).
        assertTrue(reportedOwner == address(this));
    }
}

contract OwnerCaller {
    function callOwnerOf(address target) external view returns (address) {
        return C(target).owner();
    }
}

