pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address eoa) public {
        // eoa is the fuzzed caller; we simulate a contract acting on behalf of that eoa
        vm.assume(eoa != address(0));
        // deploy a minimal helper that forwards a staticcall to c.owner()
        Proxy caller = new Proxy();
        // fund the eoa if needed (not needed here)
        vm.prank(eoa);
        // the helper calls owner() and returns it
        address returnedOwner = caller.callOwner(address(c));
        // The correct contract must return the stored _owner, which is address(this) since setUp deploys with address(this) as initial owner
        // The buggy contract returns tx.origin (which is eoa) instead, so they differ when eoa != address(this)
        assertTrue(returnedOwner == address(this));
    }
}

contract Proxy {
    function callOwner(address target) external view returns (address) {
        (bool ok, bytes memory data) = target.staticcall(abi.encodeWithSignature("owner()"));
        require(ok);
        return abi.decode(data, (address));
    }
}

