pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(string memory expectedName) public {
        string memory actualName = c.name();
        // The reference contract returns the name passed to the ERC20 constructor, which is "DCF Token".
        // The buggy version always returns "DifferentName", so for any fuzzed input not equal to "DifferentName"
        // the actual name will differ from the expected constructor parameter.
        // Since the constructor hardcodes "DCF Token", the general rule is that name() must equal that literal,
        // but the fuzzer can supply any string; we assert the behaviour that the reference satisfies:
        // if the fuzzed expectedName equals "DCF Token", name() must match; the bug breaks this.
        assertTrue(keccak256(abi.encodePacked(actualName)) == keccak256(abi.encodePacked("DCF Token")) || keccak256(abi.encodePacked(actualName)) == keccak256(abi.encodePacked(expectedName)));
    }
}

