pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0 && burnAmount <= c.balanceOf(c.pairAddress()));
        uint256 supplyBefore = c.totalSupply();
        assertTrue(supplyBefore == 2000000 * 1e18);

        vm.prank(c.pairAddress());
        c.transfer(address(0), burnAmount);

        uint256 supplyAfter = c.totalSupply();
        assertTrue(supplyAfter < 2000000 * 1e18);
    }
}

