pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 burnAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(burnAmount > 0 && burnAmount <= 2000000 * 1e18);
        // Make actor the owner to set up the scenario
        vm.prank(address(this));
        c.transferOwnership(actor);
        vm.prank(actor);
        c.setCaller(actor);
        // Approve and transfer tokens to simulate burn via pair
        vm.prank(address(this));
        c.transfer(actor, burnAmount);
        vm.prank(actor);
        c.transfer(c.pairAddress(), burnAmount);
        // The reference totalSupply equals initial supply (2000000e18) minus the burned amount,
        // while the mutant always returns a hardcoded 1000000e18
        uint256 expectedSupply = 2000000 * 1e18 - burnAmount;
        assertTrue(c.totalSupply() == expectedSupply);
    }
}

