pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 burnAmount) public {
        burnAmount = bound(burnAmount, 1, 2000000 * 1e18 - 1);
        address pair = c.pairAddress();
        vm.prank(pair);
        try c.totalSupply() returns (uint256 supplyBefore) {
            uint256 expectedAfter = supplyBefore - burnAmount;
            vm.prank(pair);
            try c.totalSupply() returns (uint256 supplyAfter) {
                assertTrue(supplyAfter == expectedAfter);
            } catch { assertTrue(false); }
        } catch { assertTrue(false); }
    }
}

